styles:
.theme-boxes {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
      gap: 1rem;
    }
    .container-theme {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      padding: 1rem 1.1rem;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg);
      color: var(--is-text);
      box-shadow: var(--is-shadow);
      min-height: 8rem;
    }
    .container-theme__head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }
    .container-theme__title {
      font-weight: 650;
      font-size: 0.95rem;
    }
    .container-theme__hint {
      margin: 0;
      font-size: 0.85rem;
      color: var(--is-text-soft);
    }
    .container-theme__chip {
      display: inline-flex;
      align-items: center;
      gap: 0.35em;
      padding: 0.35em 0.65em;
      border-radius: var(--is-radius-sm);
      background: var(--is-control-bg);
      color: var(--is-control-text);
      font-size: 0.8rem;
      border: 1px solid var(--is-control-border);
    }
